{"description":"Profile mj_forward vs mj_step components","cmd":"cd /app && python - <<'PY'
import mujoco, time, numpy as np
m = mujoco.MjModel.from_xml_path('model_ref.xml')
d = mujoco.MjData(m)

def bench(fn, N=500):
    for _ in range(30): fn()
    t0=time.perf_counter()
    for _ in range(N): fn()
    return (time.perf_counter()-t0)/N*1e6

for _ in range(30): mujoco.mj_step(m,d)
d.qpos += 0.01*np.sin(np.arange(m.nq))
mujoco.mj_forward(m,d)
print('mj_forward', bench(lambda: mujoco.mj_forward(m,d)), 'us')
print('mj_step', bench(lambda: mujoco.mj_step(m,d)), 'us')
print('mj_step1', bench(lambda: mujoco.mj_step1(m,d)), 'us')
print('mj_step2', bench(lambda: mujoco.mj_step2(m,d)), 'us')
try:
    print('mj_Euler', bench(lambda: mujoco.mj_Euler(m,d)), 'us')
except Exception as e: print('mj_Euler err', e)
try:
    print('mj_RungeKutta', bench(lambda: mujoco.mj_RungeKutta(m,d)), 'us')
except Exception as e: print('mj_RungeKutta err', e)
