{"description":"Check solver enum values and test timing per solver","cmd":"cd /app && python - <<'PY'
import mujoco, numpy as np, time
FS = mujoco.mjtState.mjSTATE_FULLPHYSICS
ref = mujoco.MjModel.from_xml_path('model_ref.xml')
# enum info
print('mjtSolver values:')
for name in dir(mujoco.mjtSolver):
    if name.startswith('mjSOL'): print(' ', name, getattr(mujoco.mjtSolver, name))
print('mjtIntegrator:')
for name in dir(mujoco.mjtIntegrator):
    if name.startswith('mjINT'): print(' ', name, getattr(mujoco.mjtIntegrator, name))

def sim(model, seed, total=2.0):
    data = mujoco.MjData(model)
    nstep = int(total / model.opt.timestep)
    rng = np.random.default_rng(seed)
    data.qpos += rng.normal(0, 0.01, size=data.qpos.shape)
    mujoco.mj_forward(model, data)
    for _ in range(nstep):
        mujoco.mj_step(model, data)
    state = np.zeros(mujoco.mj_stateSize(model, FS))
    mujoco.mj_getState(model, data, state, FS)
    return state

def bench(m, N=1000):
    d = mujoco.MjData(m)
    for _ in range(50): mujoco.mj_step(m,d)
    t0=time.perf_counter()
    for _ in range(N): mujoco.mj_step(m,d)
    return (time.perf_counter()-t0)/N*1e6

seed=123
state_ref=sim(ref,seed)
for solver in [0,1,2,3]:
    m = mujoco.MjModel.from_xml_path('model_ref.xml')
    m.opt.solver = solver
    try:
        s = sim(m, seed)
        diff = np.linalg.norm(s-state_ref)
        ts = bench(m)
        print(f'solver={solver} ({mujoco.mjtSolver(solver).name}) diff={diff:.3e} time={ts:.1f}us')
    except Exception as e:
        print(f'solver={solver} FAIL {e}')
PY"}
